package de.lowfin.tv;
import org.json.*;
import org.junit.*;
import java.time.*;
import java.util.*;
import static org.junit.Assert.*;
public class GuideWindowTest {
    private final long start=Instant.parse("2026-11-01T12:00:00Z").toEpochMilli();
    private JSONObject item(String channel,String title,long from,long to){return Json.obj("ChannelId",channel,"Name",title,"StartDate",Instant.ofEpochMilli(start+from*60_000).toString(),"EndDate",Instant.ofEpochMilli(start+to*60_000).toString());}
    @Test public void clipsLongShowsAndFillsExactTimelineWithoutDistortingDurations(){List<GuideWindow.Cell> cells=GuideWindow.cells(Json.arr(item("a","End",60,180),item("a","Start",-100,20)),"a",start);assertEquals(3,cells.size());assertEquals("Start",cells.get(0).programme.optString("Name"));assertNull(cells.get(1).programme);assertEquals(40*60_000L,cells.get(1).end-cells.get(1).start);assertEquals("End",cells.get(2).programme.optString("Name"));assertEquals(start,cells.get(0).start);assertEquals(start+GuideWindow.DURATION,cells.get(2).end);}
    @Test public void malformedWrongChannelAndZeroLengthCannotConsumeTimeline(){List<GuideWindow.Cell> cells=GuideWindow.cells(Json.arr(item("b","Other",0,120),item("a","Zero",30,30),Json.obj("ChannelId","a","StartDate","bad","EndDate","bad"),item("a","Already ended",-20,0),item("a","Later",120,130)),"a",start);assertEquals(1,cells.size());assertNull(cells.get(0).programme);assertEquals(GuideWindow.DURATION,cells.get(0).end-cells.get(0).start);}
    @Test public void overlapsAndDuplicateEntriesDoNotAddWidth(){JSONObject a=item("a","One",0,90);List<GuideWindow.Cell> cells=GuideWindow.cells(Json.arr(a,a,item("a","Two",60,120)),"a",start);assertEquals(2,cells.size());assertEquals(start+90*60_000L,cells.get(1).start);assertEquals(GuideWindow.DURATION,cells.stream().mapToLong(c->c.end-c.start).sum());}
    @Test public void changingChannelKeepsTheSameTimeAndNormalizesGuidFormats(){String id="12345678abcd1234abcd123456789012";List<GuideWindow.Cell> cells=GuideWindow.cells(Json.arr(item("12345678-abcd-1234-abcd-123456789012","One",0,40),item(id,"Two",40,120)),id,start);assertEquals(2,cells.size());assertEquals(0,GuideWindow.nearest(cells,start-1));assertEquals(1,GuideWindow.nearest(cells,start+40*60_000L));assertEquals(1,GuideWindow.nearest(cells,start+200*60_000L));}
    @Test public void nowWindowUsesLocalHalfHourAndHandlesDst(){TimeZone previous=TimeZone.getDefault();try{TimeZone.setDefault(TimeZone.getTimeZone("Europe/Berlin"));Instant instant=Instant.parse("2026-10-25T01:46:59Z");assertEquals(Instant.parse("2026-10-25T01:30:00Z").toEpochMilli(),GuideWindow.now(instant));}finally{TimeZone.setDefault(previous);}}
    @Test public void airingUsesOriginalDatesEvenWhenTheCellIsClippedByTheVisibleWindow(){List<GuideWindow.Cell> cells=GuideWindow.cells(Json.arr(item("a","Long",-100,20)),"a",start);GuideWindow.Cell first=cells.get(0);assertTrue(first.airing(start-50*60_000L));assertTrue(first.airing(start));assertFalse(first.airing(start+20*60_000L));assertFalse(cells.get(1).airing(start+30*60_000L));}
    @Test public void timelineParsesEachProgrammeDateOnceAndFocusDoesNotParseAgain() throws Exception {
        java.util.concurrent.atomic.AtomicInteger reads=new java.util.concurrent.atomic.AtomicInteger();JSONObject first=new JSONObject(item("a","First",-10,20).toString()){@Override public String getString(String key) throws JSONException{if(key.equals("StartDate")||key.equals("EndDate"))reads.incrementAndGet();return super.getString(key);}},second=new JSONObject(item("a","Second",20,160).toString()){@Override public String getString(String key) throws JSONException{if(key.equals("StartDate")||key.equals("EndDate"))reads.incrementAndGet();return super.getString(key);}};List<GuideWindow.Cell> cells=GuideWindow.cells(Json.arr(second,first),"a",start);assertEquals(4,reads.get());for(int i=0;i<300;i++)for(GuideWindow.Cell cell:cells)cell.airing(start+i*1000L);assertEquals(4,reads.get());
    }
}
